904    inline bool sanitize (hb_sanitize_context_t *c, unsigned int version) const
   905    {
   906      TRACE_SANITIZE (this);
   907      if (!length.sanitize (c) ||
   908          length < min_size ||
   909          !c->check_range (this, length))
   910        return_trace (false);
   911
   912      if (!c->check_array (featureZ.arrayZ, featureCount))
   913        return_trace (false);
   914
   915      const ChainSubtable *subtable = &StructAtOffset<ChainSubtable> (&featureZ, featureZ[0].static_size * featureCount);
   916      unsigned int count = subtableCount;
   917      for (unsigned int i = 0; i < count; i++)
   918      {
   919        if (!subtable->sanitize (c))
   920          return_trace (false);
   921        subtable = &StructAfter<ChainSubtable> (*subtable);
   922      }
   923
   924      return_trace (true);
   925    }
